# Script beats for london-two-cities (long-form #1). Loaded by episode3d.py; script.md is generated from this file.
# "ch" = chapter card shown at the start of that beat.  Second voice (sid 26) reads quotes.
BEATS = [
    # ---------------- cold open
    {"id": "hook", "era": "modern", "lead": 0.12, "tail": 0.3, "pace": 1.05,
     "vo": "The City of London's financial towers stand roughly inside the line of a Roman wall. The wall is mostly gone. The power it fenced in is not."},
    {"id": "promise", "era": "modern", "lead": 0.15, "tail": 0.35, "pace": 1.06,
     "vo": "Because London is really two cities. One grew up around money, inside that wall. The other grew up around a king, a short boat ride up the river. For a thousand years they've watched each other. By the end, you'll know who built what, who blinked first, and why the money city still has its own mayor and its own police."},
    # ---------------- chapter 1: the wall
    {"id": "c1a", "era": "medieval", "ch": ("Chapter 1", "The <span class=\"k\">wall</span>"), "lead": 1.8, "tail": 0.3, "pace": 1.07,
     "vo": "Rewind to around {AD 50|A D fifty}. There's no London here. Just a wide tidal river, marsh, and two low hills on the north bank. The Romans had invaded Britain a few years earlier, and they needed a way across the Thames."},
    {"id": "c1b", "era": "medieval", "lead": 0.15, "tail": 0.3, "pace": 1.06,
     "vo": "So they bridged it, and a trading town grew up at the north end. They called it Londinium. It started as a port, and keep that in mind, because it matters for everything that follows."},
    {"id": "c1c", "era": "siege", "lead": 0.15, "tail": 0.35, "pace": 1.11,
     "vo": "Then, around {AD 60|A D sixty}, Boudica, queen of the {Iceni|Eye-seeny}, leads a revolt against Roman rule. Her army reaches Londinium, and burns it."},
    {"id": "c1d", "era": "medieval", "lead": 0.2, "tail": 0.3, "pace": 1.06,
     "vo": "Rome comes back, and this time it builds to last. A forum. A great two-storey hall, the basilica. Within a few decades, Londinium is probably the capital of Roman Britain, and the governor lives here."},
    {"id": "c1e", "era": "medieval", "lead": 0.15, "tail": 0.35, "pace": 1.07,
     "vo": "And around {AD 200|A D two hundred}, they wrap it in stone. Roughly three kilometres of wall, about six metres high, built from something like eighty-five thousand tons of ragstone, brought from Kent."},
    {"id": "c1g", "era": "medieval", "lead": 0.15, "tail": 0.3, "pace": 1.05,
     "vo": "Roads ran out through gates in it, and you still know their names, from Tube stations and street signs: Aldgate, Bishopsgate, Moorgate, Ludgate, Newgate. Moorgate came later, in the Middle Ages, but the line it cut through was Roman."},
    {"id": "c1f", "era": "medieval", "lead": 0.3, "tail": 0.35, "pace": 1.14, "pause": 0.35,
     "vo": "Here's what gets me. That wall outlived the empire that built it, by more than a thousand years. Every ruler who came after had to deal with it. And with the people behind it."},
    # ---------------- chapter 2: fortress London
    {"id": "c2a", "era": "medieval", "ch": ("Chapter 2", "Fortress <span class=\"k\">London</span>"), "lead": 1.8, "tail": 0.3, "pace": 1.07,
     "vo": "Around {410|four ten}, Roman rule in Britain ends. Within a few decades, the town inside the wall is largely empty. The wall just stands there, guarding almost nothing."},
    {"id": "c2b", "era": "medieval", "lead": 0.15, "tail": 0.3, "pace": 1.05,
     "vo": "When the Anglo-Saxons build a new trading town, around the year {600|six hundred}, they put it outside the walls, about a mile west, along what's now the Strand. They call it Lundenwic. Later its site gets called the old settlement, {Ealdwic|Eeld-wick}. You still say it today: Aldwych."},
    {"id": "c2c", "era": "siege", "lead": 0.15, "tail": 0.3, "pace": 1.09,
     "vo": "Then the Vikings arrive. Raid after raid. And in {871|eight seventy-one}, a Viking army spends the winter in London, probably camped inside the old Roman walls. Suddenly, those walls look useful again."},
    {"id": "c2d", "era": "medieval", "lead": 0.2, "tail": 0.3, "pace": 1.06,
     "vo": "By {886|eight eighty-six}, Alfred the Great has London. He is said to have repaired the Roman wall, and life moves back inside. The place gets a new name: {Lundenburh|Lunden-burr}. Fortress London."},
    {"id": "c2d2", "era": "medieval", "lead": 0.15, "tail": 0.3, "pace": 1.06,
     "vo": "Alfred puts {Æthelred|Ethelred} of Mercia, who will become his son-in-law, in charge of it, and fortified settlements guard the bridge, probably including one at its southern end, {Southwark|Suthuck}. London is now built to hold off an army, and the people inside it know their own value."},
    {"id": "c2e", "era": "medieval", "lead": 0.15, "tail": 0.35, "pace": 1.09,
     "vo": "This is where the City of London, with a capital C, really begins. A walled town of traders that can defend itself. Remember that, because the next kings are going to have to deal with it."},
    # ---------------- chapter 3: the king moves west
    {"id": "c3a", "era": "medieval", "ch": ("Chapter 3", "The king moves <span class=\"k\">west</span>"), "lead": 1.8, "tail": 0.3, "pace": 1.06,
     "vo": "Edward the Confessor, king from {1042|ten forty-two}, makes a choice that still shapes London. He doesn't build inside the City. He goes upriver, to a marshy island called Thorney, and builds a great abbey there. The West Minster."},
    {"id": "c3b", "era": "medieval", "lead": 0.15, "tail": 0.3, "pace": 1.06,
     "vo": "Next to it, he builds a palace, so he can watch his abbey go up. And just like that, London has two centres. Merchants inside the wall. The crown out west."},
    {"id": "c3c", "era": "medieval", "lead": 0.15, "tail": 0.35, "pace": 1.09,
     "vo": "The abbey is consecrated at the end of {1065|ten sixty-five}. Edward dies days later. And on Christmas Day, {1066|ten sixty-six}, a Norman duke is crowned in Edward's brand new abbey."},
    {"id": "c3d", "era": "siege", "lead": 0.2, "tail": 0.35, "pace": 1.07,
     "vo": "William the Conqueror now has a problem. One of the biggest, richest towns in his new kingdom sits behind a wall, full of people he has to win over. So he does two things at once. First, the carrot."},
    {"id": "c3e", "era": "medieval", "lead": 0.15, "tail": 0.3, "pace": 1.05,
     "vo": "In {1067|ten sixty-seven}, he sends the City a tiny document, about the size of a bookmark, written in English, not French. It says Londoners keep their laws, as they were under King Edward, and that he won't let anyone wrong them. The City's archives still have it."},
    {"id": "c3e2", "era": "medieval", "lead": 0.2, "tail": 0.35, "pace": 1.12, "pause": 0.3,
     "vo": "I think that's a clever move. It grants nothing new. It just promises not to take anything away. It treats the City less like a conquered town and more like a business partner he can't afford to lose. But he didn't only send a letter."},
    {"id": "c3f", "era": "siege", "lead": 0.3, "tail": 0.3, "pace": 1.07,
     "vo": "Then, the stick. In the south-east corner of the Roman wall, he starts a castle. Its great stone keep, the White Tower, goes up from around {1078|ten seventy-eight}, twenty-seven metres tall, built right into the corner of the old wall."},
    {"id": "c3g", "era": "siege", "lead": 0.15, "tail": 0.2, "pace": 1.09,
     "vo": "A chronicler of the conquest, William of {Poitiers|Pwah-tee-ay}, described the first Norman fortifications in London, back in {1066|ten sixty-six}."},
    {"id": "c3q", "era": "siege", "lead": 0.15, "tail": 0.45, "pace": 1.16, "voice_sid": 26,
     "vo": "\"Certain fortifications were completed in the city against the restlessness of the huge and brutal populace.\""},
    {"id": "c3h", "era": "medieval", "lead": 0.2, "tail": 0.35, "pace": 1.07,
     "vo": "The Tower's strongest defences faced the City, and one archaeologist thinks that was deliberate. Later, his son, William the Second, builds Westminster Hall out west, seventy-three metres long, probably the biggest hall in Europe at the time. In one story, he called it a mere bedchamber compared to what he had planned."},
    # ---------------- chapter 4: the twist
    {"id": "c4a", "era": "renaissance", "ch": ("Chapter 4", "Who holds the <span class=\"k\">leash</span>?"), "lead": 1.8, "tail": 0.35, "pace": 1.06,
     "vo": "Quick recap, because this is where it flips. The king has the abbey, the palace and the Tower. The City has a wall, a slip of parchment, and the one thing kings always run short of."},
    {"id": "c4b", "era": "renaissance", "lead": 0.35, "tail": 0.4, "pace": 1.18, "pause": 0.4,
     "vo": "Money."},
    {"id": "c4c", "era": "renaissance", "lead": 0.2, "tail": 0.3, "pace": 1.06,
     "vo": "By {1189|eleven eighty-nine}, the City has its own mayor, {Henry Fitz-Ailwin|Henry Fitz Aylwin}. And in {1215|twelve fifteen}, King John is in a war with his own barons. He needs London on his side. So he grants Londoners the right to choose their mayor every year."},
    {"id": "c4c2", "era": "renaissance", "lead": 0.15, "tail": 0.3, "pace": 1.06,
     "vo": "Think about who that mayor answers to. Not the king's court out west. The merchants inside the wall. Over the next centuries the City's trades organise into guilds, the livery companies, and their members still help pick the mayor today."},
    {"id": "c4d", "era": "renaissance", "lead": 0.15, "tail": 0.3, "pace": 1.09,
     "vo": "It doesn't save him. The rebels get into London anyway. And when Magna Carta is sealed that summer, London is the only city it names."},
    {"id": "c4q", "era": "renaissance", "lead": 0.15, "tail": 0.45, "pace": 1.13, "voice_sid": 26,
     "vo": "\"The city of London is to have all its ancient liberties and free customs, both on land and water.\""},
    {"id": "c4e", "era": "renaissance", "lead": 0.2, "tail": 0.35, "pace": 1.11, "pause": 0.3,
     "vo": "And the mayor is one of the people appointed, with the barons, to make sure the king sticks to it. Think about that. The king built a fortress to watch the City. Less than a hundred and fifty years later, the City is helping to watch the king."},
    {"id": "c4f", "era": "renaissance", "lead": 0.15, "tail": 0.35, "pace": 1.07,
     "vo": "There is a catch, and it's still honoured. Every new Lord Mayor swears loyalty to the Crown, today at the Royal Courts of Justice. The journey upriver to Westminster to pledge loyalty is how the Lord Mayor's Show began, and a version of it still rolls through the City every November."},
    # ---------------- chapter 5: two fires
    {"id": "c5a", "era": "siege", "ch": ("Chapter 5", "Two <span class=\"k\">fires</span>"), "lead": 1.8, "tail": 0.3, "pace": 1.07,
     "vo": "September {1666|sixteen sixty-six}. A fire starts in a bakery on Pudding Lane and burns for about four days. Roughly thirteen thousand houses, eighty-seven churches and old St Paul's are gone."},
    {"id": "c5b", "era": "renaissance", "lead": 0.15, "tail": 0.3, "pace": 1.06,
     "vo": "King Charles the Second finally has a chance to redraw the City. Within days, Christopher Wren hands him a plan. Straight streets, open squares. The king is said to have liked it. It went nowhere."},
    {"id": "c5c", "era": "renaissance", "lead": 0.15, "tail": 0.35, "pace": 1.07,
     "vo": "The landowners wanted their plots back where they were, and buying them out would have cost a fortune. So the City rebuilt itself, mostly on its old street lines, in brick or stone by law. The king got a new cathedral, Wren's St Paul's. He didn't get a new map."},
    {"id": "c5c2", "era": "renaissance", "lead": 0.15, "tail": 0.3, "pace": 1.06,
     "vo": "Even the arguments needed special handling. Parliament set up a Fire Court, with senior royal judges, to settle landlords against tenants fast, so building could start instead of waiting years for ordinary lawsuits."},
    {"id": "c5d", "era": "19c", "lead": 0.3, "tail": 0.3, "pace": 1.06,
     "vo": "Now jump west, to the sixteenth of October, {1834|eighteen thirty-four}. Westminster is Parliament's home by now. And somebody has decided to get rid of a pile of old tally sticks."},
    {"id": "c5e", "era": "19c", "lead": 0.15, "tail": 0.3, "pace": 1.06,
     "vo": "Tally sticks were notched pieces of wood the royal treasury used for centuries to keep its accounts. Two cartloads of them go into the furnaces under the House of Lords. A chimney catches, and by evening the palace is on fire."},
    {"id": "c5f", "era": "siege", "lead": 0.15, "tail": 0.35, "pace": 1.07,
     "vo": "Huge crowds watch from the streets and the river. Westminster Hall, William the Second's bedchamber, survives, saved by its thick medieval walls, a change in the wind, and the firefighters."},
    {"id": "c5g", "era": "19c", "lead": 0.3, "tail": 0.35, "pace": 1.12, "pause": 0.3,
     "vo": "And here's the contrast I love. The City, after its fire, insisted on its old map. Parliament, after its fire, ran a competition, and asked for something that looked old on purpose."},
    {"id": "c5h", "era": "19c", "lead": 0.15, "tail": 0.35, "pace": 1.06,
     "vo": "The rules said Gothic or Elizabethan. Ninety-seven designs came in. Charles Barry won, with Augustus {Pugin|Pew-jin} drawing the details and reshaping the clock tower that now holds Big Ben. A brand new palace, dressed up as the Middle Ages."},
    # ---------------- chapter 6: today
    {"id": "c6a", "era": "modern", "ch": ("Chapter 6", "Walk it <span class=\"k\">today</span>"), "lead": 1.8, "tail": 0.3, "pace": 1.07,
     "vo": "So, walk it today. Start at Tower Hill. Right by the station there's a tall chunk of the Roman wall. And a short walk away, the White Tower still stands in the old wall's corner."},
    {"id": "c6b", "era": "modern", "lead": 0.15, "tail": 0.3, "pace": 1.06,
     "vo": "Head north-west, and the towers close in: banks, insurers, glass. They sit in the Square Mile, run not by an ordinary council but by the City of London Corporation, with its own Lord Mayor, who is not the Mayor of London, and its own police force."},
    {"id": "c6c", "era": "modern", "lead": 0.15, "tail": 0.35, "pace": 1.06,
     "vo": "Its elections are unusual too. Alongside residents, businesses in the City get to appoint voters. Critics say that gives finance a privileged voice in British politics. Defenders say it represents the hundreds of thousands who work there, not only the fewer than ten thousand who live there."},
    {"id": "c6c2", "era": "modern", "lead": 0.15, "tail": 0.3, "pace": 1.06,
     "vo": "And it keeps a permanent official, the Remembrancer, who watches Parliament for the City and lobbies on new laws. The old relationship, a king out west and a City that negotiates with him, never really ended. It just changed clothes."},
    {"id": "c6d", "era": "modern", "lead": 0.2, "tail": 0.35, "pace": 1.07,
     "vo": "Then take the river west, the way the mayors used to. Barry's Gothic palace, with Westminster Hall tucked inside it, more than nine hundred years old. And the abbey next door, where Edward the Confessor is buried, and where monarchs are still crowned."},
    # ---------------- closer
    {"id": "c6d2", "era": "modern", "lead": 0.15, "tail": 0.3, "pace": 1.06,
     "vo": "Or walk it overland. You'll pass Aldwych, the old Saxon town outside the walls, and on Fleet Street a dragon on a pillar marks Temple Bar, roughly where the City meets Westminster. Two cities, one street."},
    {"id": "close", "era": "modern", "lead": 0.4, "tail": 0.5, "pace": 1.16, "pause": 0.35,
     "vo": "About two thousand years, and London still has two centres. One built around a wall. One built around a crown. The wall is mostly gone. The border isn't."},
    {"id": "punch", "era": "modern", "lead": 0.3, "tail": 0.9, "pace": 1.07,
     "vo": "If you want the story of how the City nearly got a new map, there's a short about the Great Fire on the channel. And if you know another city that's secretly two cities, tell me which one."},
]
